import {
  forwardRef,
  type HTMLAttributes,
  type ReactElement,
  type ReactNode,
} from "react";

import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardFooter,
  CardHeader,
} from "@/components/ui/card";
import { cn } from "@/lib/cn";

/** Presentation for a published game; fetching and navigation stay with the host. */
export type GameShareCardProps = HTMLAttributes<HTMLDivElement> & {
  heading: ReactNode;
  eyebrow?: ReactNode;
  cover?: ReactNode;
  /** A host-owned link or button, presented as the primary play action. */
  action: ReactElement;
};

/** Compose a game's cover, share details and play action in the enclosing theme. */
export const GameShareCard = forwardRef<HTMLDivElement, GameShareCardProps>(
  function GameShareCard(
    { heading, eyebrow, cover, action, children, className, ...props },
    ref,
  ) {
    return (
      <Card {...props} className={cn("caps-game-share", className)} ref={ref}>
        {cover ? <div className="caps-game-share-cover">{cover}</div> : null}
        <CardHeader>
          {eyebrow}
          <h3 className="caps-game-share-heading">{heading}</h3>
        </CardHeader>
        <CardContent className="gap-sm">{children}</CardContent>
        <CardFooter>
          <Button asChild variant="primary" className="caps-game-share-action">
            {action}
          </Button>
        </CardFooter>
      </Card>
    );
  },
);

import { STIPE_SPACING_NAMES } from "@fungi.computer/stipe";
import { cva } from "class-variance-authority";
import { createCn } from "cn/config";

/** A conditional class value accepted by cn. */
export type { ClassValue } from "cn";
export { cva };

/** Merge conditional classes with Tailwind rules and Stipe's named spacing. */
export const cn = createCn({
  extend: { theme: { spacing: [...STIPE_SPACING_NAMES] } },
});

/** Resolve a typed React class-name prop before merging its classes. */
export function resolveClassName<State>(
  className: string | ((state: State) => string | undefined) | undefined,
  state: State,
): string | undefined {
  return typeof className === "function" ? className(state) : className;
}

.caps-game-share.--caps-card-edge:
var(
      --caps-card-interactive-edge,
      color-mix(
        in oklab,
        var(--color-base-content) calc(13% + (1 - var(--depth)) * 87%),
        transparent
      )
    )
